--- a/app/src/main/java/com/example/customer/service/CustomerService.java
+++ b/app/src/main/java/com/example/customer/service/CustomerService.java
@@ -33,4 +33,17 @@
     public Customer create(Customer customer) {
         return customerRepository.save(customer);
     }
+
+    /**
+     * Updates ONLY the email address of an existing customer -- name and
+     * every other field are left exactly as stored. Reuses getById() so a
+     * missing customer id fails the same way (404 via NoSuchElementException
+     * -> GlobalExceptionHandler) as every other read/write path in this
+     * service, rather than duplicating that not-found logic here.
+     */
+    public Customer updateEmail(Long id, String newEmail) {
+        Customer customer = getById(id);
+        customer.setEmail(newEmail);
+        return customerRepository.save(customer);
+    }
 }

